    $scope.LoadDynamicData = function (params, type) {


        if ($scope.IsDynamicCheckInMandatory && type === 'PageLoad') {
            $scope.SubTab = 11;
            console.log("count 1");
            $q.all([
                eHnoteMainAppointmentService.GetPatientDynamicStatusForAppointmentList(params)
            ]).then(function (resp) {
                if (resp[0].data.length !== 0) {
                    $scope.DynamicStatusCountList = resp[0].data || [];

                    console.log("dynamic Called");
                    if (params.RoleId === 43 || params.RoleId === 16) {//DOCTOR
                        $scope.SubTab = 14;
                        $scope.changeActiveSubTab(1, 'Waiting', $scope.SubTab, "RefreshPageLoad");
                    }


                    if (params.RoleId === 1 && $scope.SuffixId !== 13) {
                        $scope.SubTab = 14;
                        $scope.changeActiveSubTab(1, 'Waiting', $scope.SubTab, "RefreshPageLoad");
                    }


                    if (params.RoleId === 1 && $scope.SuffixId === 13) {
                        $scope.SubTab = 20;
                        $scope.changeActiveSubTab(12, 'Waiting', $scope.SubTab, "RefreshPageLoad");
                    }
                    if (params.RoleId === 59 || params.RoleId === 11 || params.RoleId === 4 || params.RoleId === 8 || params.RoleId === 74) {//RECEPTIONIST
                        $scope.SubTab = 11;
                        eHnoteMainAppointmentService.GetAllNewBookedAppointmentforAllDoctors(params, OnGetListofAppointmentSuccess, OnGetListofAppointmentError);
                        // $scope.navtoPrintPatientAppointments();
                    }
                    if (params.RoleId === 2 || params.RoleId === 20 || params.RoleId === 21 || params.RoleId === 64) { // Receptionist
                        if ($scope.userLoginDetails.RoleID === 20 || params.RoleId === 20) {
                            $scope.SubTab = 11;
                            $scope.changeActiveSubTab('', '', $scope.SubTab, "RefreshPageLoad")
                        }
                        else if ($scope.userLoginDetails.RoleID === 21 || params.RoleId === 21) {
                            $scope.SubTab = 16;
                            $scope.changeActiveSubTab('', '', $scope.SubTab, "RefreshPageLoad")
                        }
                        else if ($scope.userLoginDetails.RoleID === 64 || params.RoleId === 64) {
                            $scope.SubTab = 16;
                            $scope.changeActiveSubTab('', '', $scope.SubTab, "RefreshPageLoad")
                        }
                        else {
                            $scope.SubTab = 19;
                            $scope.changeActiveSubTab(10, 'Waiting', $scope.SubTab, "RefreshPageLoad")
                        }
                    }
                    if (params.RoleId === 61) {//aR
                        $scope.SubTab = 1;
                        $scope.changeActiveSubTab(8, 'Waiting', $scope.SubTab, "RefreshPageLoad")
                    }
                    if (params.RoleId === 10 || params.RoleId === 62 || params.RoleId === 63) {//OPTOM
                        $scope.SubTab = 2;
                        $scope.changeActiveSubTab(2, 'Waiting', $scope.SubTab, "RefreshPageLoad")
                    }
                    if (params.RoleId === 54) {//DILATION
                        $scope.SubTab = 3;
                        $scope.changeActiveSubTab(3, 'Waiting', $scope.SubTab, "RefreshPageLoad")
                    }
                    if (params.RoleId === 18) {//counsellor
                        $scope.SubTab = 4;
                        $scope.changeActiveSubTab(4, 'Waiting', $scope.SubTab, "RefreshPageLoad")
                    }
                    if (params.RoleId === 55) {//investigator
                        $scope.SubTab = 5;
                        $scope.changeActiveSubTab(5, 'Waiting', $scope.SubTab, "RefreshPageLoad")
                    }
                    if (params.RoleId === 19) {//biller
                        $scope.SubTab = 17;
                        $scope.changeActiveSubTab(9, 'Waiting', $scope.SubTab, "RefreshPageLoad")
                    }

                    if (params.RoleId === 65 || params.RoleId === 66 || params.RoleId === 67 || params.RoleId === 68 || params.RoleId === 69) {//biller
                        $scope.SubTab = 19;
                        $scope.changeActiveSubTab(10, 'Waiting', $scope.SubTab, "RefreshPageLoad");
                    }


                }
            }, function (err) {
                console.log(err);
            });
        }
        else if ($scope.IsDynamicCheckInMandatory && type === 'CheckInPageload') {
            $scope.changesubtabBased(params);

        }
        else {
            $scope.SubTab = 11;
            eHnoteMainAppointmentService.GetAllNewBookedAppointmentforAllDoctors(params, OnGetListofAppointmentSuccess, OnGetListofAppointmentError);
        }

    }

