                    $scope.allUserList = response.rows || [];
                    $scope.OnlyNusrseAnesthetistRoles = [];
                    $scope.OnlyNusrseAnesthetistRoles = $scope.allUserList.filter((x) => x.RoleId == 8 || x.RoleId == 25);

                    $scope.CheckinChecklistArray = [];
