    function GetMedicineType(item) {
        var med = '';
        switch (item.MedicineType) {
            case "TAB":
                med = "TABLET";
                break;
            case "T":
                med = "TABLET";
                break;
            case "INJ":
                med = "injection";
                break;
            case "GEL":
                med = "gel";
                break;
            case "CAP":
                med = "capsules";
                break;
            case "SUS":
                med = "oral suspension";
                break;
            case "OIN":
                med = "Ointment";
                break;
            case "CRE":
                med = "cream";
                break;
            case "SOL":
                med = "solution";
                break;
            case "SYR":
                med = "syrup";
                break;
            case "LIQ":
                med = "liquid";
                break;
            case "DRO":
                med = "drops";
                break;
            case "VIA":
                med = "vial";
                break;
            case "KIT":
                med = "kit";
                break;
            case "SPR":
                med = "spray";
                break;
            case "LOT":
                med = "lotion";
                break;
            case "RES":
                med = "respirator";
                break;
            case "INH":
                med = "inhaler";
                break;
            case "SUP":
                med = "supplement";
                break;
            case "INS":
                med = "Insulin";
                break;
        }
        return med;
    }
    function ConcatMeal(item) {
        var meal = "";
        if (item.MedicineType === "SUS" || item.MedicineType === "LIQ" || item.MedicineType === "SYR" || item.MedicineType === "SOL") {
            if (item.Dosage1.toString() === "" && item.Dosage2.toString() === "" && item.Dosage4.toString() === "") {
                meal += '-';
            } else {
                meal += item.Dosage1 === "" ? "0-" : item.Dosage1 + "-";
                meal += item.Dosage2 === "" ? "0-" : item.Dosage2 + "-";
                meal += item.Dosage4 === "" ? "0" : item.Dosage4 + "(ml)";
            }
        } else if (item.MedicineType === "DRO") {
            if (item.Dosage1.toString() === "" && item.Dosage2.toString() === "" && item.Dosage4.toString() === "") {
                meal += '-';
            } else {
                meal += item.Dosage1 === "" ? "0-" : item.Dosage1 + "-";
                meal += item.Dosage2 === "" ? "0-" : item.Dosage2 + "-";
                meal += item.Dosage4 === "" ? "0" : item.Dosage4 + " Drop(s)";
            }
        } else {
            if (item.Dosage1.toString() === "" && item.Dosage2.toString() === "" && item.Dosage4.toString() === "") {
                meal += '-';
            } else {
                meal += item.Dosage1 === "" ? "0-" : item.Dosage1 + "-";
                meal += item.Dosage2 === "" ? "0-" : item.Dosage2 + "-";
                meal += item.Dosage4 === "" ? "0" : item.Dosage4 + "";
            }
        }
        return meal;
    }
