    function isTimeTwoGreaterThanTimeOne(timeOne, timeTwo) {

        var result = false;
        var currentDate = new Date();
        var currentYear = currentDate.getFullYear();
        var currentMonth = currentDate.getMonth();
        var currentDay = currentDate.getDate();
        var timeOne = timeOne;
        var timeTwo = timeTwo;
        var dateOne = new Date(`${currentYear}-${currentMonth + 1}-${currentDay} ${timeOne}`);
        var dateTwo = new Date(`${currentYear}-${currentMonth + 1}-${currentDay} ${timeTwo}`);
        var timeOneUnix = dateOne.getTime();
        var timeTwoUnix = dateTwo.getTime();
        if (timeTwoUnix - timeOneUnix >= 15 * 60 * 1000) {
            result = true;
        } else {
            result = false;
        }
        return result;
    };

    function getdtTimes(hours, mins) {
        var h = hours, m = mins;
        var thistime = (h > 12) ? (h - 12 + ':' + m + ' PM') : (h + ':' + m + ' AM');
        console.log(thistime);
        return thistime;
    }

    function encryptImage(base64Data, secretKey) {
        var key = CryptoJS.enc.Utf8.parse(secretKey); // Convert key to WordArray
        var encrypted = CryptoJS.AES.encrypt(base64Data, key, {
            mode: CryptoJS.mode.ECB,
            padding: CryptoJS.pad.Pkcs7
        });
        return encrypted.toString();
    }

    $scope.decryptData = function (data) {
        if (data) {
            try {
                let decryptedThumbnail = atob(data);

                // Check if the decrypted data is valid Base64
                if (decryptedThumbnail.startsWith("data:image")) {
                    return decryptedThumbnail;
                } else {
                    return data;
                }
            } catch (error) {
                // If decryption fails, use original value
                return data;
            }
        }
        //    return atob(data); // Decode Base64
    };

