    function getApptimeSplit(time) {
        var t = time.split(':');
        dur = {};
        dur['hr'] = parseInt(t[0]);
        dur['min'] = parseInt(t[1].substr(0, 2));
        dur['ampm'] = t[1].substr(2);
        return dur;
    }
    function getAppNewFormattedDate(currdt) {
        var month = new Array(12);
        month[0] = "January";
        month[1] = "February";
        month[2] = "March";
        month[3] = "April";
        month[4] = "May";
        month[5] = "June";
        month[6] = "July";
        month[7] = "August";
        month[8] = "September";
        month[9] = "October";
        month[10] = "November";
        month[11] = "December";
        return currdt.getDate() < 10 ? "0" + currdt.getDate() : currdt.getDate() + "-" + month[currdt.getMonth()] + "-" + currdt.getFullYear();
    }
