                        //if (sTime.appointmentStatus == "C") {
                        //    newtitle = '<img src="img/appt-list/xmark-solid.svg" width="12" style="margin-right:5px;"/>' + title
                        //} else {
                        //    var isconfirmedappt = sTime.IsConfirmedAppointment || false;
                        //    if (isconfirmedappt) {
                        //        newtitle = '<img src="img/appt-list/check-solid.svg" width="12" style="margin-right:5px;"/>' + title;
