    $scope.alertOnDrop = function (event, delta, revertFunc, jsEvent, ui, view) {
        //api.destroy();
        //chooseAction(event, delta, revertFunc, jsEvent, ui, view);
        //if (event.AppointmentDetails.appointmentStatus == 'B') {

        console.log(event.AppointmentDetails.appointmentStatus);


        //drag and drop appt into break or block slot case -- start (22-09-2023) - prod issue
        let breakcounter = 0;
        angular.forEach($scope.eventsList, function (item) {
            if (item.IsBreakEvent) {
                let st = $filter('date')(new Date(item.SlotInfo.StartTime), "HH:mm");
                st = st.split(":").join("");
                let et = $filter('date')(new Date(item.SlotInfo.EndTime), "HH:mm");
                et = et.split(":").join("");

                let startTime = $filter("date")(new Date(event.start), "HH:mm");
                startTime = startTime.split(":").join("");
                let endTime = $filter('date')(new Date(event.end), 'HH:mm');
                endTime = endTime.split(":").join("");

                if ((startTime >= st && startTime < et) || (endTime > st && endTime <= et)) {
                    breakcounter++
                }
            }
        });

        if (breakcounter > 0) {
            alertify.error("This slot is blocked, please unblock the slot to move the appointment");
            revertFunc();
            return;
        }

        // drag and drop appt into break or block slot case -- end

        if (event.AppointmentDetails.appointmentStatus !== 'C' && event.AppointmentDetails.appointmentStatus !== 'R') {

            var GivenDate = moment(event.start).format('DD-MMM-YYYY');
            var CurrentDate = new Date();
            GivenDate = parseCalenderDate(GivenDate);
            if (GivenDate > CurrentDate) {

            } else {
                var given1 = $filter('date')(new Date(GivenDate), "MM-dd-yyyy");
                var current1 = $filter('date')(new Date(CurrentDate), "MM-dd-yyyy");
                if (given1 === current1) {
                    var todaystartTime = $filter("date")(new Date(event.start), "HH:mm");
                    var todaytime = $filter('date')(new Date(), 'HH:mm');
                    if (todaystartTime < todaytime) {
                        alertify.error('This Time Slot Has Already Ended!');
                        revertFunc();
                        return false;
                    }
                }
            }

            var startTime = $filter("date")(new Date(event.start), "HH:mm");
            var endTime = $filter('date')(new Date(event.end), 'HH:mm');
            var start1 = startTime.replaceAll(":", "");
            var filteredDOcObj = $filter("filter")($scope.Calendardoctorlist1, function (iterator, ind) { return iterator.DoctorID === parseInt(doctorInfo.doctorid); });
            var OverAllStartTime1 = $scope.CalenderDoctorAvailableSlots.StartTime.replaceAll(":", "");
            var OverAllEndTime1 = $scope.CalenderDoctorAvailableSlots.EndTime.replaceAll(":", "");
            if ($scope.CalenderDoctorAvailableSlots.IsAdvancedSchedule) {

                // number of appointments for this slot
                let apptsCounter = 0;
                angular.forEach($scope.eventsList, function (item) {
                    if (!item.IsBreakEvent) {
                        let st = item.AppointmentDetails.startTime.split(":");
                        st = st[0] + ":" + st[1];
                        if (st === startTime) {
                            apptsCounter++;
                        }
                    }
                });

                var maxapptcounter = 0;
                var visitrsncounter = 0;
                angular.forEach($scope.CalenderDoctorAvailableSlots.SlotsList, function (item) {
                    if (startTime == item.StartTime) {
                        if (item.MaxNumberOfSlots == apptsCounter || apptsCounter > item.MaxNumberOfSlots) {
                            maxapptcounter++;
                        }
                        let tempArray = $filter('filter')(item.VisitReasons, { "ReasonId": event.AppointmentDetails.VisitTypeId }, true);
                        if (tempArray.length > 0) {
                            visitrsncounter = 1;
                        } else {
                            visitrsncounter = 2;
                        }
                    }
                });

            }
            else {
                // number of appointments for this slot
                let apptsCounter = 0;
                angular.forEach($scope.eventsList, function (item) {
                    if (!item.IsBreakEvent) {
                        let st = item.AppointmentDetails.startTime.split(":");
                        st = st[0] + ":" + st[1];
                        if (st === startTime) {
                            apptsCounter++;
                        }
                    }
                });

                var maxapptcounter = 0;
                var visitrsncounter = 0;
                angular.forEach($scope.CalenderDoctorAvailableSlots.SlotsList, function (item) {
                    let s1 = item.StartTime.replaceAll(":", "");
                    let e1 = item.EndTime.replaceAll(":", "");
                    if (start1 >= s1 && start1 < e1) {
                        if (item.MaxNumberOfSlots == apptsCounter || apptsCounter > item.MaxNumberOfSlots) {
                            maxapptcounter++;
                        }
                        let tempArray = $filter('filter')(item.VisitReasons, { "VisitTypeId": event.AppointmentDetails.AppointmentTypeId }, true);
                        if (tempArray.length > 0) {
                            visitrsncounter = 1;
                        } else {
                            visitrsncounter = 2;
                        }
                    }
                });

            }

            if (maxapptcounter > 0) {

                $scope.mInstanceAdd = $uibModal.open({
                    "templateUrl": "templates/uibpopups/ConfirmationPopupMaxSlots.html",
                    "backdrop": "static",
                    "scope": $scope,
                    "keyboard": false,
                    "size": "md",
                    "resolve": {
                        "type": function () { return 1; }
                    },
                    "controller": function ($scope, $uibModal, $uibModalInstance, eHnotePatientPVService, type) {
                        let pageName = $location.url();
                        $scope.type = type;
                        $scope.MaxSlotObj = {
                            "Remarks": "",
                            "status": ""
                        };

                        $scope.continuemaxslotbookappointment = function () {
                            if (pageName == '/op') {
                                if (!$scope.UserAccessRights.AllAccessRights.OPUnblockSlotAccess) {
                                    alertify.error("You dont have access,please contact your manager");
                                    return false;
                                }
                            }

                            if (pageName == '/crm') {
                                if (!$scope.UserAccessRights.AllAccessRights.CRMUnblockSlotAccess) {
                                    alertify.error("You dont have access,please contact your manager");
                                    return false;
                                }
                            }
                            if ($scope.MaxSlotObj.Remarks === "") {
                                alertify.error("Please Enter Remarks");
                                return false;
                            }

                            $scope.MaxSlotObj.status = "Yes";
                            $uibModalInstance.close($scope.MaxSlotObj);
                        };

                        $scope.cancelmaxslotBookAppointment = function () {
                            $scope.MaxSlotObj.status = "No";
                            $uibModalInstance.close($scope.MaxSlotObj);
                        }
                    }
                });
                $scope.mInstanceAdd.result.then(function (resp) {

                    if (resp.status === "Yes") {
                        $scope.ChangeAppointmentDoctor1(event, resp.Remarks);
                    } else {
                        revertFunc();
                    }
                }, function (cancel) {
                });

                return;
            }
            if ((parseInt(OverAllStartTime1) <= parseInt(start1)) && (parseInt(start1) < parseInt(OverAllEndTime1)) && visitrsncounter == 2) {
                $scope.mInstanceAdd = $uibModal.open({
                    "templateUrl": "templates/uibpopups/ConfirmationPopupMaxSlots.html",
                    "backdrop": "static",
                    "scope": $scope,
                    "keyboard": false,
                    "size": "md",
                    "resolve": {
                        "type": function () { return 2; }
                    },
                    "controller": function ($scope, $uibModal, $uibModalInstance, eHnotePatientPVService, type) {
                        let pageName = $location.url();
                        $scope.type = type;
                        $scope.MaxSlotObj = {
                            "Remarks": "",
                            "status": ""
                        };

                        $scope.continuemaxslotbookappointment = function () {
                            if (pageName == '/op') {
                                if (!$scope.UserAccessRights.AllAccessRights.OPUnblockSlotAccess) {
                                    alertify.error("You dont have access,please contact your manager");
                                    return false;
                                }
                            }

                            if (pageName == '/crm') {
                                if (!$scope.UserAccessRights.AllAccessRights.CRMUnblockSlotAccess) {
                                    alertify.error("You dont have access,please contact your manager");
                                    return false;
                                }
                            }
                            if ($scope.MaxSlotObj.Remarks === "") {
                                alertify.error("Please Enter Remarks");
                                return false;
                            }

                            $scope.MaxSlotObj.status = "Yes";
                            $uibModalInstance.close($scope.MaxSlotObj);
                        };

                        $scope.cancelmaxslotBookAppointment = function () {
                            $scope.MaxSlotObj.status = "No";
                            $uibModalInstance.close($scope.MaxSlotObj);
                        }
                    }
                });
                $scope.mInstanceAdd.result.then(function (resp) {

                    if (resp.status === "Yes") {
                        $scope.ChangeAppointmentDoctor1(event, resp.Remarks);
                    } else {
                        revertFunc();
                    }
                }, function (cancel) {
                });
                return;
            }

            if ((parseInt(OverAllStartTime1) <= parseInt(start1)) && (parseInt(start1) < parseInt(OverAllEndTime1))) {

                $scope.ChangeAppointmentDoctor1(event);

            } else {
                if (filteredDOcObj[0].SlotStartTime != "00:00" && filteredDOcObj[0].SlotEndTime != "00:00") {
                    var r = alertify.confirm("<b class='txt-centre'>Confirm !</b><h4 class='txt-body-centre'> You Have Selected Non-business Hours, Do You Wish to Continue?</h4>", function () {
                        $scope.ChangeAppointmentDoctor1(event);
                    }, function () {
                        revertFunc();
                    });
                } else {
                    revertFunc();
                }
            }


        } else {
            revertFunc();
        }
    };
