            if ($scope.selectedOPUsers.SelectedDoctorsList.length > 0) {
                angular.forEach($scope.Calendardoctorlist1, function (citem, $index) {
                    citem.isChecked = false;
                });
            }

            if ($scope.selectedOPUsers.AppoinmentBookingTypeID != 0) {
                $scope.AppoinmentBookingTypeobj1.AppoinmentBookingTypeID = $scope.selectedOPUsers.AppoinmentBookingTypeID;
            }
            if ($scope.selectedOPUsers.AppoinmentBookingTypeID == 0) {
                $scope.AppoinmentBookingTypeobj1.AppoinmentBookingTypeID = "";
            }
            angular.forEach($scope.PatientTagList1, function (Mitem) {
                Mitem.IsChecked = false;
            });

            if ($scope.selectedOPUsers.selectedPatientTagList.length > 0) {
                angular.forEach($scope.selectedOPUsers.selectedPatientTagList, function (item) {
                    angular.forEach($scope.PatientTagList1, function (kitem) {
                        if (kitem.HospitalEquipmentId === item.HospitalEquipmentId) {
                            kitem.IsChecked = true;
                        }
                    });
                });

            }
            var PatientTagcheckedArray = _.where($scope.PatientTagList1, { IsChecked: true });
            $scope.TagPatientObj.AllPatientTagsCheck = PatientTagcheckedArray.length > 0 && $scope.PatientTagList1.length === PatientTagcheckedArray.length ? true : false;
            if ($scope.TagPatientObj.AllPatientTagsCheck) {
                $scope.TagPatientObj.SelectTag = 'All';
            }
            if (!$scope.TagPatientObj.AllPatientTagsCheck && PatientTagcheckedArray.length > 0) {
                $scope.TagPatientObj.SelectTag = 'Selected';
            } else if (!$scope.TagPatientObj.AllPatientTagsCheck && PatientTagcheckedArray.length == 0) {
                $scope.TagPatientObj.SelectTag = 'Select Tag Patient';
            }

            /*$scope.mainCalendarView.AllDoctorscheck = true;*/
