    $scope.changeCalendarDatefullCalendar = function (date) {

        // `date` arrives as either a Date object or a "MM-DD-YYYY" string (e.g. from navtoTodayDate).
        // moment(date) with no explicit format falls back to ambiguous/engine-dependent parsing for
        // non-ISO strings, which is exactly what made Safari/iOS show the wrong "today" — route it
        // through normalizeToYMD first so parsing is always explicit and in local time.
        var normalizedDate = normalizeToYMD(date);
        $scope.SearchObj.ConsultationDt = moment(normalizedDate, 'YYYY-MM-DD').format("MM-DD-YYYY");

        var selectDate = moment(normalizedDate, 'YYYY-MM-DD', true);
        var todayDate = moment().startOf('day');

        if (selectDate.isValid()) {
            $scope.DisabledClickInCalendar = selectDate.isBefore(todayDate);
        } else {
            console.warn("Invalid date format:", date);
            $scope.DisabledClickInCalendar = false; // or true if you want to disable by default
        }
        var checkedArrayList = [];
        if ($scope.MultiselectDoctorlist.length > 0) {
            checkedArrayList = _.where($scope.MultiselectDoctorlist, { isChecked: true });
        }

        var checkedBranchesArrayList = [];
        if ($scope.ApptBranchLocations.length > 0) {
            var filteredBArray = $filter('filter')($scope.ApptBranchLocations, { 'IsChecked': true });
            checkedBranchesArrayList = filteredBArray;
        }


        var obj = {
            "SelectedDoctorsList": checkedArrayList || [],
            "OPFromDate": $scope.SearchObj.ConsultationDt || '',
            "BookingTypesArray": $scope.BookingTypesArray1 || [],
            "AppointmentStatusArray": $scope.AppointmentStatusArray1 || [],
            "BookedstatusFilterList": $scope.BookedstatusFilterList1 || [],
            "ProfileStatusList": $scope.ProfileStatusList1 || [],
            "SelectedBranchesList": checkedBranchesArrayList || []
        };
        $scope.calendarView2 = "day";
        eHnoteMasterDataService.addSelectedOPUsers(obj);


        console.log($scope.mainCalendarView.MainTab + "__mainCalendarView.MainTab");
        if ($scope.mainCalendarView.MainTab == 1) {
            // $scope.activeEvent = 'day';
            $scope.viewDate = safeNewDate(normalizedDate);
            $scope.loadCalenderEvent('day');
            $scope.calendarView = 'day';

            $scope.SelectedDoctorcalendar = 'singleDoctor';
            $scope.loadAppointments($scope.selectedDoctor, '');

        } else {

            $scope.$broadcast('allCalendarView');
        }
        // clear details when changing dates
        $scope.clearSelectedSlots();
        $scope.clearEventSelectedSlots();
        $scope.clearBreakDetails();
    }



