    $scope.changesubtabBased = function (params) {
        console.log("count 4");
        $q.all([
            eHnoteMainAppointmentService.GetPatientDynamicStatusForAppointmentList(params)
        ]).then(function (resp) {
            if (resp[0].data.length !== 0) {
                $scope.DynamicStatusCountList = resp[0].data || [];
                console.log("dynamic etrt");
                if ($scope.SubTab === 14) { // doctor
                    $scope.changeActiveSubTab(1, 'Waiting', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 11) { // All
                    eHnoteMainAppointmentService.GetAllNewBookedAppointmentforAllDoctors(params, OnGetListofAppointmentSuccess, OnGetListofAppointmentError);
                }
                else if ($scope.SubTab === 19) { // rece
                    $scope.changeActiveSubTab(10, 'Waiting', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 1) {
                    $scope.changeActiveSubTab(8, 'Waiting', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 2) { // tech
                    $scope.changeActiveSubTab(2, 'Waiting', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 3) {
                    $scope.changeActiveSubTab(3, 'Waiting', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 4) { // consellor
                    $scope.changeActiveSubTab(4, 'Waiting', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 5) {
                    $scope.changeActiveSubTab(5, 'Waiting', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 17) { // billing
                    $scope.changeActiveSubTab(9, 'Waiting', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 20) { // opth
                    $scope.changeActiveSubTab(12, 'Waiting', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 16) { // not checkin
                    $scope.changeActiveSubTab('', '', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 12) { // checkin
                    $scope.changeActiveSubTab('', '', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 13) { // checkout
                    $scope.changeActiveSubTab('', '', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 22) { // rece
                    $scope.changeActiveSubTab(10, 'Active', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 7) { // tech
                    $scope.changeActiveSubTab(2, 'Active', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 21) { // opth
                    $scope.changeActiveSubTab(12, 'Active', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 15) { // doctor
                    $scope.changeActiveSubTab(1, 'Active', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 9) { // consellor
                    $scope.changeActiveSubTab(4, 'Active', $scope.SubTab, "RefreshPageLoad")
                }
                else if ($scope.SubTab === 18) { // rece
                    $scope.changeActiveSubTab(9, 'Active', $scope.SubTab, "RefreshPageLoad")
                }

                if (doctorinfo.RoleID == 1 || doctorinfo.RoleID == 43) {
                    var obj = {
                        "selectedDoctor": {
                            "DoctorID": doctorinfo.doctorid
                        }
                    }
                    $rootScope.$broadcast("AppointmentTypefilter", obj);
                } else {
                    var obj = {
                        "selectedDoctor": {
                            "DoctorID": 0
                        }
                    }
                    $rootScope.$broadcast("AppointmentTypefilter", obj);
                }

            }
        }, function (err) {
            console.log(err);
        });
    };

