    $scope.openpatientcheckinpopup = function (item, ind) {
        // If status is completed → open transfer popup directly
        if (item.ProfileStatusName === "Completed") {

            if ($scope.filteredAppointmentArray.length > 0) {

                let row = $filter('filter')($scope.filteredAppointmentArray,
                    { 'AppointmentID': item.AppointmentID }, true)[0] || {};

                let index = $scope.filteredAppointmentArray.indexOf(row);

                $scope.onClickCheckInPopup(row, index); // Transfer popup open avuthundi
            }
            else {
                $scope.onClickCheckInPopup();
            }

            return; // Stop check-in popup
        }

        var resolveobj = {
            "PatientID": item.PatientID,
            "AlertNoteTypeId": 1,
            "AppointmentID": item.AppointmentID,
            "BranchId": item.BranchId,
            "ConsultationDt": item.ConsultationDt,
            "DoctorID": item.DoctorID,
            "AppointmentStatusId": item.AppointmentStatusId,
            "AppointmentTypeId": item.AppointmentTypeId,
            "allUserList": $scope.allUserList || [],
            "AllBranchesList": $scope.BranchesListArray || [],
            "IsFromCheckedOut": true,
            "PatientOnboardingStatus": item.PatientOnboardingStatus || ""
        };

        $scope.patientcheckinoutpopupinstance = $uibModal.open({
            "templateUrl": "templates/uibpopups/checkInCheckOutPopup.html",
            "backdrop": "static",
            "scope": $scope,
            "keyboard": false,
            "windowClass": "modal__ninety--",
            "resolve": {
                "obj": function () {
                    return resolveobj;
                }
            },
            "controller": "UsPatientCheckinheckoutCtrl"
        });
        $scope.patientcheckinoutpopupinstance.result.then(function (resp) {
            console.log(resp);
            if (resp.CloseandOpenFlag) {

                if ($scope.filteredAppointmentArray.length > 0) {
                    let row = $filter('filter')($scope.filteredAppointmentArray, { 'AppointmentID': resp.AppointmentID }, true)[0] || {};
                    let index = $scope.filteredAppointmentArray.indexOf(row);

                    if (row.VisitReasonStatus == "InActive") {
                        //    alertify.error("Visit Reason Is In-Active ! Please Update Visit Reason");
                        //    return false;
                    }
                    $scope.onClickCheckInPopup(row, index);
                } else {
                    $scope.onClickCheckInPopup();
                };
            };
        }, function (cancel) {
        });
    };

