    $scope.onClickCheckInPopup = function (item, ind) {
        if (item.BookingTypeId == 2) {
            alertify.error("Patient in waiting! Confirm appointment first. ");
            return false;
        }

        if ($scope.queueSettingObj.IsEnabled) {
            var DiffMinutes = getcurrentTimeDifferenceMinutesNew(item.StartTime);

            if (DiffMinutes > 0) {
                // var CheckTimeCurre = true;
                if (DiffMinutes > $scope.queueSettingObj.CheckInAvgTime) {
                    alertify.error("You cannot Check IN before appointment time");
                    // item.showcheckinPopup = false;
                    // item.showDynamiccheckinPopup = false;
                    return false;
                }
            }
        }

        let ConsultationDt = item.ConsultationDt || '';
        if (ConsultationDt != '') {
            $scope.IsFutureAppointmentDate = eHnotePatientDataService.IsFutureDate(item.ConsultationDt);
        }

        if ($scope.IsFutureAppointmentDate) {
            alertify.error("for future appointment Checkin/Checkout not allowed");
            return;
        }

        $scope.checkInObj.AppointmentId = item.AppointmentID;
        $scope.checkInObj.VisitReason = item.VisitReason;
        $scope.checkInObj.AttenderName = item.AttenderName;
        // item.showcheckinPopup = true;
        // item.showDynamiccheckinPopup = true;

        $scope.ApptObj.HospitalEquipmentId = item.HospitalEquipmentId || "";
        $scope.ApptObj.VisitTypeId = item.VisitTypeId || 0;
        $scope.ApptObj.AppointmentTypeId = item.AppointmentTypeId || 0;
        $scope.ApptObj.VisitReasonName = item.VisitReason || '';
        $scope.ApptObj.AppointmentStatusId = item.AppointmentStatusId || null;
        $scope.ApptObj.BookingStatusId = item.BookingStatusId || null;
        //$scope.GetVisitReason();

        $scope.Technishionsend(item, "NotCheckIN");
    };

    $scope.changePatientApptSearchTextinCalNew = function (text, type) {
        //console.log(type + "__" + text + "__" + $scope.SearchObj.searchPatientTxt);
        //console.log($scope.eventsList);
        // clear event details
        $scope.clearSelectedSlots();
        $scope.clearEventSelectedSlots();
        $scope.clearBreakDetails();
        $scope.filteredEventsList = [];
        if ($scope.mainCalendarView.MainTab == 1) {
            $timeout(function () {
                if (type == 1) {
                    if (text === "" || text === undefined) {
                        $scope.filteredEventsList = angular.copy($scope.eventsList);
                    } else {
                        $scope.filteredEventsList = $filter("filter")($scope.eventsList, { "PatientName": text }) || [];
                    }
                }
                if (type == 2) {
                    if (text === "" || text === undefined) {
                        $scope.filteredEventsList = angular.copy($scope.eventsList);
                    } else {
                        $scope.filteredEventsList = $filter("filter")($scope.eventsList, { "PatientMrNo": text }) || [];
                    }
                }
                if (type == 3) {
                    if (text === "" || text === undefined) {
                        $scope.filteredEventsList = angular.copy($scope.eventsList);
                    } else {
                        $scope.filteredEventsList = $filter("filter")($scope.eventsList, { "PatientOldMrNo": text }) || [];
                    }
                }
                if (type == 4) {
                    text = text + " 00:00:00";
                    //text = $filter('date')(new Date(text), "yyyy-MM-dd");
                    var parsedDate = new Date(text);
                    if (!isNaN(parsedDate.getTime())) {
                        text = $filter('date')(parsedDate, "yyyy-MM-dd");
                    } else {
                        // Log an error or handle the invalid date case
                        alertify.error("Invalid date format:", text);
                        // Return false or handle the error in another way
                        text = "";
                        return false;
                    }
                    if (text === "" || text === undefined) {
                        $scope.filteredEventsList = angular.copy($scope.eventsList);
                    } else {
                        $scope.filteredEventsList = $filter("filter")($scope.eventsList, function (event) {
                            // Check if the DOB in the patientInfo section matches the provided DOB
                            if (event.AppointmentDetails && event.AppointmentDetails.patientInfo) {
                                return event.AppointmentDetails.patientInfo.DOB === text;
                            }

                        }) || [];
                    }
                }
                singleCalendar().fullCalendar('removeEvents');
                singleCalendar().fullCalendar('addEventSource', $scope.filteredEventsList);
                singleCalendar().fullCalendar('rerenderEvents');
            }, 50);
        }

        if ($scope.mainCalendarView.MainTab == 2) {
            if (type !== 4) {
                let obj = {
                    "text": text,
                    "type": type
                };
                $scope.$broadcast("AllDocsCalendarFilter", obj);
            } else if (type === 4) {
                text = text + " 00:00:00";
                text = $filter('date')(new Date(text), "yyyy-MM-dd");
                let obj = {
                    "text": text,
                    "type": type
                };
                $scope.$broadcast("AllDocsCalendarFilter", obj);
            }


        }

    };

    $scope.onChangeSearchApptinCal = function (text, type) {
        text = text || "";
        if ($scope.mainCalendarView.MainTab == 1) {
            if (text === "") {
                singleCalendar().fullCalendar('removeEvents');
                singleCalendar().fullCalendar('addEventSource', $scope.eventsList);
                singleCalendar().fullCalendar('rerenderEvents');
            }
        }

        if ($scope.mainCalendarView.MainTab == 2) {
            let obj = {
                "text": text,
                "type": type
            };
            $scope.$broadcast("AllDocsCalendarFilterClear", obj);
        }
    };

