    $scope.NoShowAppointmentList = function (item) {
        if (item.AppointmentStatusId == 3 || item.AppointmentStatusId == 4) {
            alertify.error("Appointment is checked out!");
            return;
        }
        $scope.modalnoshowappt = $uibModal.open({
            "templateUrl": "templates/uibpopups/NoShowAppointmentPopup.html",
            "controller": "USNoShowAppointmentPopupCtrl",
            "size": "lg",
            "backdrop": "static",
            "keyboard": false,
            "resolve": {
                "ApptObject": function () { return item; },
                "allUserList": function () { return angular.copy($scope.allUserList); }
            },

        });
        $scope.modalnoshowappt.result.then(function (Type) {
            if (Type == "Save") {
                if ($scope.mainAppointmentView.isCalendarorList == 'list' || $scope.mainCalendarView.MainTab == 1) {
                    $scope.loadAppointments($scope.selectedDoctor, 'PageLoad');
                }
                var obj = {
                    "selectedDoctor": $scope.selectedDoctor
                }

                if ($scope.activeEvent === 'Calendar1') {
                    $scope.loadappt();
                }
                if ($scope.mainCalendarView.MainTab == 2 && $scope.mainAppointmentView.isCalendarorList == 'calendar') {
                    $scope.filterSelectedDoctorsonCalendar();
                    $scope.clearSelectedSlots();
                    $scope.clearEventSelectedSlots();
                }

                $scope.clearSelectedSlots();
                $scope.clearEventSelectedSlots();
                $scope.loadAppointments($scope.selectedDoctor, '');
            }

        }, function (cancel) {

        });
    }


    $scope.NoShowAppointmentDeatailsFrmSingCalender = function (item) {
        var obj = {
            "PatientName": item.PatientName,
            "AppointmentDate": item.date,
            "AppointmentStartTime": item.StartTime,
            "DoctorName": item.DoctorName,
            "IsPatientEmailInd": false,
            "IsPatientSmsInd": false,
            "AppointmentId": item.infoobj.AppointmentDetails.appointmentID,
            "AppointmentDetails": item.infoobj.AppointmentDetails,

        }

        $scope.NoShowAppointmentList(obj);
    }
    $scope.NoShowAppointmentDeatailsFrmOp = function (item) {
        var Sarray = item.StartTime.split(":");
        var stime = Sarray[0] + ":" + Sarray[1];
        var date = moment(item.ConsultationDt).format();
        var earray = item.EndTime.split(":");
        var etime = earray[0] + ":" + earray[1];
        var apptime = item.AppointmentID;
        var VisitTypeId = item.VisitTypeId || "";
        VisitTypeId = VisitTypeId != '' ? VisitTypeId : 0;
        var VisitRemarks = item.VisitRemarks || "";
        $scope.AppDate = [stime, etime, apptime, item.VisitReason ? item.VisitReason : "", item.ReferralSourceId ? item.ReferralSourceId : "", VisitTypeId, VisitRemarks];
        $scope.calenderDate = moment(date).format("DD-MMM-YYYY" + " " + stime);
        let surgeryList = [];
        if (item.AppointmentTypeId == 7) {
            surgeryList = angular.copy(item.PreAdmSurgeryList);

        } else if (item.AppointmentTypeId == 4 || item.AppointmentTypeId == 14) {
            surgeryList = angular.copy(item.SurgeryList);
        }

        var obj = {
            "PatientId": item.PatientID || null,
            "PatientName": item.PatientDetails.FullName,
            "AppointmentDate": item.ConsultationDt,
            "AppointmentStartTime": item.StartTime,
            "DoctorName": item.DoctorFullName,
            "IsPatientEmailInd": false,
            "IsPatientSmsInd": false,
            "AppointmentId": item.AppointmentID,
            "PageName": "NoShow",
            "AppDate": $scope.AppDate,
            "ispatientExistsval": true,
            "calenderDate": $scope.calenderDate,
            'IsComingFrom': '',
            "DoctorId": item.DoctorID,
            "StartTime": stime || "",
            "EndTime": etime,
            'type': 'op',
            "SurgeryList": surgeryList || [],
            "NoShowReasonId": item.NoShowReasonId,
            "NoShowReasonRemarks": item.NoShowReasonRemarks,
            "VisitReason": item.VisitReason,
        }

        $scope.NoShowAppointmentList(obj);
    }




