    $scope.getPatientInsuranceDetails = function (item) {
        if (!item || item === undefined) {
            alertify.error("Invalid Patient ID"); // Show error if item is empty, null, or undefined
            return; // Exit the function early
        }
        else {

            eHnoteInsuranceService.getPatientInsuranceDtls(item, 0, true)
                .then(function (resp) {
                    if (resp.data.Status === "Success") {
                        //let ActiveInsuranceList = resp.data.rows.length > 0
                        //    ? $filter('filter')(resp.data.rows, { 'StatusId': 1 }, true) || []
                        //    : [];

                        $scope.PatientInsuranceSummary = resp.data.rows;
                        angular.forEach($scope.PatientInsuranceSummary, function (item) {
                            item.ToShowInsAccodianView = true;
                        });

                        $scope.ExpiredPatientInsuranceList = resp.data.ExpiredPatientInsuranceList || [];
                    }
                })
                .catch(function () {
                    alertify.error("Getting Data Failed");
                });
        }

    }

