                    if ($scope.PatientDetailsInfo.FirstName === "") {
                        alertify.error("Please Enter Patient First Name");
                        return;
                    }
                    //if ($scope.PatientDetailsInfo.FirstName.length < 3) {
                    //    alertify.error("Please Enter Patient First Name");
