    function decryptImage(encryptedData, secretKey) {
        try {
            if (!encryptedData || !secretKey) {
                throw new Error("Missing encryptedData or secretKey");
            }

            var key = CryptoJS.enc.Utf8.parse(secretKey); // Convert key to WordArray

            var decrypted = CryptoJS.AES.decrypt(encryptedData, key, {
                mode: CryptoJS.mode.ECB,
                padding: CryptoJS.pad.Pkcs7
            });




            var originalData = decrypted.toString(CryptoJS.enc.Utf8);
            if (!originalData) throw new Error("Decryption failed");

            let byteCharacters = atob(originalData.split(',')[1]);
            let byteNumbers = new Array(byteCharacters.length);
            for (let i = 0; i < byteCharacters.length; i++) {
                byteNumbers[i] = byteCharacters.charCodeAt(i);
            }
            let byteArray = new Uint8Array(byteNumbers);
            let blob = new Blob([byteArray], { type: "image/png" });

            let blobUrl = URL.createObjectURL(blob);

            // Set timeout to revoke the URL after rendering
            setTimeout(() => {
                URL.revokeObjectURL(blobUrl);
            }, 5000); // Revoke after 5 seconds

            return blobUrl;


        } catch (e) {
            console.error("Error decrypting image:", e.message);
            return "img/sprite-sheet/user-square.svg"; // Fallback image
        }
    }

    $scope.decryptImage1 = function (encryptedData) {
        const secretKey = "YourSecretKey123";
        let decryptedImage = decryptImage(encryptedData, secretKey);

        // If decryption fails, return a default placeholder image
        return decryptedImage ? decryptedImage : "img/sprite-sheet/user-square.svg";
    };


    $scope.decryptImage = function (encryptedData) {
        if (!encryptedData || encryptedData.trim() === "") {
            console.warn("Empty or undefined Thumbnail, returning default image.");
            return "img/sprite-sheet/user-square.svg";
        }

        const secretKey = "YourSecretKey123"; // Ensure 16 characters

        try {
            var key = CryptoJS.enc.Utf8.parse(secretKey);
            var decrypted = CryptoJS.AES.decrypt(encryptedData, key, {
                mode: CryptoJS.mode.ECB,
                padding: CryptoJS.pad.Pkcs7
            });

            var originalData = decrypted.toString(CryptoJS.enc.Utf8);
            if (!originalData) throw new Error("Decryption failed");

            return originalData;
        } catch (e) {
            console.error("Error decrypting image:", e.message, "Encrypted Data:", encryptedData);
            return "img/sprite-sheet/user-square.svg"; // Fallback image
        }
    };


