                function OnAddPatientError1(err) {
                    $scope.IsLittleMoreAboutYouSave = false;
                    alertify.error("Failed to save changes");
                }

                //Referral Start
                function isNewReferralDocument(ditem) {
                    return !!ditem && ditem.file instanceof File;
                }

                function getPendingReferralDocuments() {
                    return $filter("filter")($scope.referralDocumentDetails, function (ditem) {
                        return isNewReferralDocument(ditem) && ditem.DeleteInd !== "Y";
                    }) || [];
                }

                function getDeletedReferralDocuments() {
                    return $filter("filter")($scope.referralDocumentDetails, function (ditem) {
                        return ditem.DeleteInd === "Y" && !isNewReferralDocument(ditem);
                    }) || [];
                }

                function getReferralDocumentId(ditem) {
                    return ditem.FileId || ditem.DocumentId || ditem.DocumentID || 0;
                }

                function formatReferralDocumentSize(size) {
                    if (size === null || size === undefined || size === "") {
                        return "";
                    }
                    if (angular.isString(size) && !/^\d+(\.\d+)?$/.test(size.trim())) {
                        return size.trim();
                    }
                    var bytes = Number(size);
                    if (!isFinite(bytes) || bytes <= 0) {
                        return "";
                    }
                    return $filter("number")(bytes / 1024, 1) + " KB";
                }

                function getReferralDocumentsToAdd() {
                    var documents = [];
                    angular.forEach(getPendingReferralDocuments(), function (ditem) {
                        documents.push({
                            "S3URL": ditem.S3URL || "",
                            "FileTypeId": 10,
                            "Remarks": "",
                            "DeleteInd": "N",
                            "DocumentID": 0,
                            "DisplayName": ditem.FileName || ditem.DisplayName || "",
                            "FileName": ditem.FileName || ditem.DisplayName || "",
                            "FileExt": ditem.file.type || ditem.FileExt || "",
                            "DocumentSize": formatReferralDocumentSize(ditem.file.size)
                        });
                    });
                    return documents;
                }

                function getReferralDocumentsToDelete() {
                    var documents = [];
                    angular.forEach(getDeletedReferralDocuments(), function (ditem) {
                        documents.push({
                            "DocumentId": getReferralDocumentId(ditem),
                            "DeleteInd": "Y"
                        });
                    });
                    return documents;
                }

                function syncReferralDocumentsAfterSave(response) {
                    //Files just uploaded, by name - kept only for viewing when the response has no S3URL for them
                    var uploadedFiles = {};
                    angular.forEach(getPendingReferralDocuments(), function (ditem) {
                        uploadedFiles[ditem.FileName || ditem.DisplayName] = ditem.file;
                    });

                    var storedDocuments = (response && (response.DocumentDetails || response.TempDocumentDetails)) || null;
                    if (angular.isArray(storedDocuments)) {
                        angular.forEach(storedDocuments, function (ditem) {
                            if (!ditem.S3URL) {
                                ditem.LocalFile = uploadedFiles[ditem.FileName || ditem.DisplayName];
                            }
                        });
                        $scope.referralDocumentDetails = storedDocuments;
                        return;
                    }
                    var documents = [];
                    angular.forEach($scope.referralDocumentDetails, function (ditem) {
                        if (ditem.DeleteInd === "Y") {
                            return;
                        }
                        //Saved now - not a new upload any more, keep the file only to view it
                        if (isNewReferralDocument(ditem)) {
                            ditem.LocalFile = ditem.file;
                        }
                        delete ditem.file;
                        documents.push(ditem);
                    });
                    $scope.referralDocumentDetails = documents;
                }

                $scope.visibleReferralDocuments = function () {
                    return $filter("filter")($scope.referralDocumentDetails, function (ditem) {
                        return ditem.DeleteInd !== "Y";
                    }) || [];
                };

                $scope.referralDocumentSize = function (ditem) {
                    if (isNewReferralDocument(ditem)) {
                        return formatReferralDocumentSize(ditem.file.size);
                    }
                    return formatReferralDocumentSize(ditem.DocumentSize || ditem.FileSize);
                };

                $scope.selectReferralDocuments = function ($files) {
                    $files = $files || [];
                    angular.forEach($files, function (file) {
                        $scope.referralDocumentDetails.push({
                            "file": file,
                            "FileName": file.name,
                            "DisplayName": file.name,
                            "FileExt": file.type || "",
                            "FileSize": file.size,
                            "DocumentID": 0,
                            "DeleteInd": "N"
                        });
                    });
                };

                $scope.openReferralDocument = function (ditem) {
                    if (ditem.S3URL) {
                        window.open(ditem.S3URL, "_blank", "noopener");
                        return;
                    }
                    var localFile = isNewReferralDocument(ditem) ? ditem.file : ditem.LocalFile;
                    if (localFile instanceof File) {
                        var fileUrl = URL.createObjectURL(localFile);
                        window.open(fileUrl, "_blank");
                        $timeout(function () {
                            URL.revokeObjectURL(fileUrl);
                        }, 60000);
                        return;
                    }
                    alertify.error("Document is not available to view, please reopen the patient form");
                };

                $scope.removeReferralDocument = function (ditem) {
                    alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are you sure want to delete? </h4>", function () {
                        var index = $scope.referralDocumentDetails.indexOf(ditem);
                        if (index === -1) {
                            return;
                        }
                        if (isNewReferralDocument(ditem)) {
                            $scope.referralDocumentDetails.splice(index, 1);
                        } else {
                            ditem.DeleteInd = "Y";
                        }
                        $scope.$apply();
                    }, function () {
                        return;
                    });
                };

                $scope.ReferralDocumentsSave = function () {
                    return $scope.PatientDetailsSave();
                };
                //Referral End

                $scope.removeImage = function () {
                    alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are you sure want to delete? </h4>", function () {
                        $scope.IsModifedLogo = false;
                        $scope.PatientDetailsInfo.S3URL = '';
                        $scope.PatientDetailsInfo.PatientProfilePicDetails = [];
                        $scope.file = "";
                        $scope.$apply();
                    }, function () {
                        return;
                    });
                }

                $scope.selectPrintImgLogo1 = function (file) {
                    $scope.PatientDetailsInfo.PatientProfilePicDetails = [];

                    $scope.isLogoDefault = false;
                    $scope.isLogoThumbnailDefault = true;
                    $scope.isLogoS3URLDefault = false;
                    $scope.IsModifedLogo = true;

                    $scope.PatientDetailsInfo.S3URL = '';
                    $scope.file = "";

                    $scope.file = file;
                    if ($scope.file != null) {
                        var pName = $scope.file.name, name = "";
                        $scope.PatientDetailsInfo.FileName = pName;
                        $scope.PatientDetailsInfo.FileExt = $scope.file.type;
                        var type = $scope.file.type.split("/")[1];
                        if (pName.length > 9) {
                            name = pName.substring(0, 9) + "..." + "." + type;
                        } else {
                            name = angular.copy(pName) + '.' + type;
                        }


                        var obj = {
                            "file": $scope.file,
                            "DocumentTypeId": "",
                            "DeleteInd": false,
                            "DocumentId": 0,
                            "DocumentExt": $scope.file.type,
                            "DisplayName": name,
                            "Thumbnail": ""
                        };


                        if ($scope.file.type != 'application/pdf') {
                            //    $scope.PatientDetailsInfo.PatientProfilePicDetails.push(obj);
                            let reader = new FileReader();
                            reader.onload = function (event) {
                                let img = new Image();
                                img.src = event.target.result;
                                img.onload = function () {
                                    let canvas = document.createElement("canvas");
                                    let ctx = canvas.getContext("2d");

                                    // Define thumbnail size (e.g., 100x100 pixels)
                                    let maxWidth = 100;
                                    let maxHeight = 100;
                                    let width = img.width;
                                    let height = img.height;

                                    // Maintain aspect ratio
                                    if (width > height) {
                                        height *= maxWidth / width;
                                        width = maxWidth;
                                    } else {
                                        width *= maxHeight / height;
                                        height = maxHeight;
                                    }

                                    canvas.width = width;
                                    canvas.height = height;
                                    ctx.drawImage(img, 0, 0, width, height);

                                    // Convert to Base64 and store it
                                    obj.Thumbnail = canvas.toDataURL("image/png");

                                    $scope.PatientDetailsInfo.PatientProfilePicDetails = $scope.PatientDetailsInfo.PatientProfilePicDetails || [];
                                    $scope.PatientDetailsInfo.PatientProfilePicDetails.push(obj);
                                    if (!$scope.$$phase) {
                                        $scope.$apply();
                                    }

                                };
                            };

                            reader.readAsDataURL(file);
                        }

                        angular.element("input[type='file']").val(null);
                    }
                };

                $scope.newcaptureimage = function () {

                    // $scope.ClosepatientPhotoUpload();
                    $scope.modelIntance = $uibModal.open({
                        "size": 'md',
                        "templateUrl": 'loadNewpopup.html',
                        "scope": $scope,
                        "backdrop": true,
                        "keyboard": false,
                        "windowClass": " ",
                    });
                };

                $scope.cancelCapturePopup = function () {
                    $scope.PatientDetailsInfo.S3URL = '';
                    $scope.PatientDetailsInfo.PatientProfilePicDetails = [];
                    $scope.modelIntance.dismiss('cancel');

                }

                $scope.save = function () {
                    var abc = document.getElementById('printresult');

                    $scope.splitStrings1 = abc.innerHTML;


                    function dataURLtoFile(dataurl, filename) {
                        var arr = dataurl.split(','), mime = arr[0].match(/:(.*?);/)[1],
                            bstr = atob(arr[1]),
                            n = bstr.length,
                            u8arr = new Uint8Array(n);
                        while (n--) {
                            u8arr[n] = bstr.charCodeAt(n);
                        }
                        return new File([u8arr], filename, { type: mime });
                    }

                    $scope.file = dataURLtoFile($scope.splitStrings1, 'Profile');
                    $scope.selectPrintImgLogo1($scope.file);

                    $scope.modelIntance.dismiss('cancel');

                };

                $scope.encryptData = function (data) {
                    return btoa(data); // Simple Base64 Encoding
                };

                $scope.changePatientAuthorization = function (AuthorizationId, Type) {

                    if (AuthorizationId === null) {
                        $scope.PatientDetailsInfo.AuthorizationId = "";
                        return false;
                    }
                    $scope.PatientDetailsInfo.ContactInfo.AuthorizationId = Type;
                    const obj = $scope.PatientDetailsInfo.ContactInfo;
                    const hasAuthId = AuthorizationId;
                    // Now apply logic based on the Type
                    switch (Type) {
                        case 1: // SMS
                            if (hasAuthId) {
                                obj.AuthSMSInd = true;
                                obj.IsPatientSmsInd = true;
                                obj.IsfutureCommunications = true;
                                obj.UnAuthorisedInd = false;
                                obj.IsPatientEmailInd = false;
                            } else {
                                obj.AuthSMSInd = false;
                                obj.IsPatientSmsInd = false;
                                if (!obj.AuthEmailInd && !obj.AuthSMSInd && !obj.AuthBothInd) {
                                    obj.IsfutureCommunications = false;
                                }
                            }
                            break;

                        case 2: //  Email

                            if (hasAuthId) {
                                obj.IsPatientEmailInd = true;
                                obj.AuthEmailInd = true;
                                obj.IsfutureCommunications = true;
                                obj.UnAuthorisedInd = false;
                                obj.IsPatientSmsInd = false;
                            } else {
                                obj.IsPatientEmailInd = false;
                                obj.AuthEmailInd = false;
                                if (!obj.AuthEmailInd && !obj.AuthSMSInd && !obj.AuthBothInd) {
                                    obj.IsfutureCommunications = false;
                                }
                            }
                            break;
                        case 3: // Both
                            if (hasAuthId) {
                                obj.IsPatientEmailInd = true;
                                obj.AuthEmailInd = true;
                                obj.AuthSMSInd = true;
                                obj.IsPatientSmsInd = true;
                                obj.AuthBothInd = true;
                                obj.IsfutureCommunications = true;
                                obj.UnAuthorisedInd = false;
                            } else {
                                obj.IsPatientEmailInd = false;
                                obj.AuthEmailInd = false;
                                obj.AuthSMSInd = false;
                                obj.IsPatientSmsInd = false;
                                obj.AuthBothInd = false;
                                //obj.UnAuthorisedInd = true;
                                if (!obj.AuthEmailInd && !obj.AuthSMSInd && !obj.AuthBothInd) {
                                    obj.IsfutureCommunications = false;
                                }
                            }
                            break;

                        case 4: // Unauthorized
                            obj.IsPatientEmailInd = false;
                            obj.AuthEmailInd = false;
                            obj.AuthSMSInd = false;
                            obj.IsPatientSmsInd = false;
                            obj.AuthBothInd = false;
                            obj.IsfutureCommunications = false;
                            obj.UnAuthorisedInd = hasAuthId ? true : false;
                            break;
                    }

                    // Final corrections
                    if (!obj.AuthEmailInd && !obj.AuthSMSInd && !obj.AuthBothInd) {
                        obj.AuthorizationId = '';
                    }
                    if ((!obj.AuthEmailInd && obj.AuthSMSInd) || (obj.AuthEmailInd && !obj.AuthSMSInd)) {
                        obj.AuthBothInd = false;
                    }
                    if (obj.AuthEmailInd && obj.AuthSMSInd) {
                        obj.IsPatientEmailInd = true;
                        obj.IsPatientSmsInd = true;
                        obj.AuthBothInd = true;
                        obj.IsfutureCommunications = true;
                        obj.UnAuthorisedInd = false;
                    }
                };

