                function getInsuranceType(identifierId) {
                    if (identifierId == 1) return "Primary";
                    if (identifierId == 2) return "Secondary";
                    if (identifierId == 4) return "Other";
                    if (identifierId == 3 || identifierId == 5) return "Tertiary";
                    return ""; // fallback
                }

                function proceedToSaveInsurance(tempInsuarance, type, EditMode) {

                    //if (tempInsuarance.ExpiryDate) {
                    //    tempInsuarance.ExpiryDate = moment(tempInsuarance.ExpiryDate, ["DD-MM-YYYY", "YYYY-MM-DD"])
                    //        .format("YYYY-MM-DD");
                    //}

                    //if (tempInsuarance.EffectiveDate) {
                    //    tempInsuarance.EffectiveDate = moment(tempInsuarance.EffectiveDate, ["DD-MM-YYYY", "YYYY-MM-DD"])
                    //        .format("YYYY-MM-DD");
                    //}

                    //if (tempInsuarance.ScanDate) {
                    //    tempInsuarance.ScanDate = moment(tempInsuarance.ScanDate, ["DD-MM-YYYY", "YYYY-MM-DD"])
                    //        .format("YYYY-MM-DD");
                    //}

                    //if (tempInsuarance.VerifiedDate) {
                    //    tempInsuarance.VerifiedDate = moment(tempInsuarance.VerifiedDate, ["DD-MM-YYYY", "YYYY-MM-DD"])
                    //        .format("YYYY-MM-DD");
                    //}

                    //if (tempInsuarance.InsuredPersonDOB) {
                    //    tempInsuarance.InsuredPersonDOB = moment(tempInsuarance.InsuredPersonDOB, ["DD-MM-YYYY", "YYYY-MM-DD"])
                    //        .format("YYYY-MM-DD");
                    //}

                    if (tempInsuarance.ExpiryDate != "") {
                        tempInsuarance.ExpiryDate = $filter('date')(tempInsuarance.ExpiryDate, 'yyyy-MM-dd');
                    }
                    if (tempInsuarance.EffectiveDate != "") {
                        tempInsuarance.EffectiveDate = $filter('date')(tempInsuarance.EffectiveDate, 'yyyy-MM-dd');
                    }
                    if (tempInsuarance.ScanDate != "") {
                        tempInsuarance.ScanDate = $filter('date')(tempInsuarance.ScanDate, 'yyyy-MM-dd');
                    }
                    if (tempInsuarance.VerifiedDate != "") {
                        tempInsuarance.VerifiedDate = $filter('date')(tempInsuarance.VerifiedDate, 'yyyy-MM-dd');
                    }
                    if (tempInsuarance.InsuredPersonDOB != "") {
                        tempInsuarance.InsuredPersonDOB = $filter('date')(tempInsuarance.InsuredPersonDOB, 'yyyy-MM-dd');
                    }


                    //var param = {
                    //    "PatientId": $scope.patientid,
                    //    "FullName": $scope.PatientFullName,
                    //    "UserId": $scope.UserId,
                    //    "HospitalId": $scope.HospitalId,
                    //    // "IsConnectToFutureAppointment": $scope.PatientInsuranceObj.IsConnectToFutureAppointment || false,
                    //    "IsConnectToFutureAppointment": TempInsuarance.IsConnectToFutureAppointment || false,
                    //    "PatientInsuranceDetails": []
                    //}
                    var param = {
                        "PatientId": PatientId,
                        "FullName": $scope.PatientDetailsInfo.FullName,
                        "HospitalId": $scope.HospitalId,
                        // "IsConnectToFutureAppointment": $scope.PatientInsuranceObj.IsConnectToFutureAppointment || false,
                        "PatientInsuranceDetails": [],
                        "AppointmentId": AppointmentId || null,

                    }
                    param.PatientInsuranceDetails.push(tempInsuarance);


                    console.log(JSON.stringify(tempInsuarance.PatientDocumentDetails))
                    console.log("param", param);
                    eHnotePatientAddressDataServices.AddupdatePatientInsurancesFromPatientportal(param, OnAddPatientSuccess, OnAddPatientError);
                    function OnAddPatientSuccess(resp) {
                        if (resp.data.Status === "Success") {
                            var resp = resp.data || {};
                            console.log(type + "_type");
                            let LogMasterPortalPatientInsuranceDetailId = tempInsuarance.MasterPortalPatientInsuranceDetailId || 0;
                            let insuranceType = getInsuranceType(tempInsuarance.IdentifierId);
                            let PayorName = tempInsuarance.PayorName || '';
                            let payor = '';
                            if (PayorName != '') {
                                payor = `(${PayorName})`;
                            }
                            let type1 = 0, ACD = '';
                            let formattedDate = $filter("date")($scope.AppointmentDt, "MM-dd-yyyy");
                            if (LogMasterPortalPatientInsuranceDetailId == 0) {
                                type1 = 2;
                                ACD = `${insuranceType} Insurance${payor} Added for Appt: ${formattedDate}`;
                            } else {
                                type1 = 3;
                                ACD = `${insuranceType} Insurance${payor} Edited for Appt: ${formattedDate}`;
                            }

                            $scope.IsShowEligibiltySave = false;
                            if (resp.PatientInsuranceDetails.length > 0) {
                                $scope.IsPatientHaveInsurance = true;
                                $scope.IsPatientDontHaveInsurance = false;
                                $scope.PatientDetailsInfo.IsPatientDontHaveInsurance = false
                                $scope.PatientDetailsInfo.IsPatientHaveInsurance = true
                                $scope.PatientInsuranceSummary = resp.PatientInsuranceDetails;
                                $scope.PatientInsuranceSummary = $scope.PatientInsuranceSummary.map(item => ({
                                    ...item,
                                    IsShowEligibiltySave: false,
                                    IsEditmode: false,
                                    ExpiryDate: item.ExpiryDate || null,
                                    EffectiveDate: item.EffectiveDate || null
                                }));
                            }
                            $scope.PatientInsuranceSummary.forEach(item => {
                                if (item.IdentifierId == 1) { item.IdentifierName = 'Primary' }
                                else if (item.IdentifierId == 2) { item.IdentifierName = 'Secondary' }
                                else if (item.IdentifierId == 3) { item.IdentifierName = 'Tertiary' }
                                else if (item.IdentifierId == 4) { item.IdentifierName = 'WorkersComp' }
                                else if (item.IdentifierId == 5) { item.IdentifierName = 'Other' }
                                item.PatientInsuranceDetailId = item.PatientInsuranceDetailId || 0;
                                item.IsEdit = true;
                                if (item.PatientInsuranceDetailId != 0) {
                                    item.IsEdit = false;
                                }
                            })
                            $scope.Registeraddpopup = true;

                            alertify.success("Changes saved successfully");
                            //$scope.AddUpdatePatientPortalLog(type1, ACD);
                            //$scope.feildValidationObj.isInsurance = isInsuranceCompleted();
                            $scope.IsSummury = true;
                            //$scope.Onboardingobj.tab++
                            $scope.PatientInsuranceObj = GetInsuranceObj();
                            //    $scope.ShowHideInsuraceeditScreen();
                            AfterPatientFormSave(true);
                        }
                    }
                    function OnAddPatientError() {
                        alertify.error("Creating  Failed");
                    }
                }

                function isSameInsurance(a, b) {
                    return a.PayorId === b.PayorId &&
                        a.PlanId === b.PlanId &&
                        a.PolicyId === b.PolicyId &&
                        a.StatusId === b.StatusId &&
                        a.IdentifierId === b.IdentifierId &&
                        (a.GroupId || '') === (b.GroupId || '') &&
                        $filter('date')(a.EffectiveDate || '', 'yyyy-MM-dd') === $filter('date')(b.EffectiveDate || '', 'yyyy-MM-dd') &&
                        $filter('date')(a.ExpiryDate || '', 'yyyy-MM-dd') === $filter('date')(b.ExpiryDate || '', 'yyyy-MM-dd') &&
                        a.PatientDocumentDetails == b.PatientDocumentDetails;
                }

                $scope.selectInsuranceFrontFileUpload = function (file, insItem, index) {
                    if (!file) return;

                    $scope.Ffile = file;
                    $scope.frontItemUpload = true;

                    var pName = file.name;
                    var ext = pName.includes(".") ? pName.split(".").pop() : (file.type.split("/")[1] || "");
                    var shortName = pName.length > 9 ? pName.substring(0, 9) + "... ." + ext : pName;

                    insItem.TempInsuranceImagesArray = insItem.TempInsuranceImagesArray || [];
                    insItem.TempInsuranceImagesArray.push({
                        file: file,
                        DeleteInd: "N",
                        DocumentId: 0,
                        DocumentExt: file.type,
                        DocumentName: shortName,
                        DisplayName: "Front"
                    });

                    angular.element("input[type='file']").val(null);

                    insItem.ScanDate = moment(new Date()).toDate();
                };

                $scope.selectInsuranceBackFileUpload = function (file, insItem, index) {
                    if (!file) return;

                    $scope.Bfile = file;
                    $scope.backItemUpload = true;

                    var pName = file.name;
                    var ext = pName.includes(".") ? pName.split(".").pop() : (file.type.split("/")[1] || "");
                    var shortName = pName.length > 9 ? pName.substring(0, 9) + "... ." + ext : pName;

                    insItem.TempInsuranceImagesArray = insItem.TempInsuranceImagesArray || [];
                    insItem.TempInsuranceImagesArray.push({
                        file: file,
                        DeleteInd: "N",
                        DocumentId: 0,
                        DocumentExt: file.type,
                        DocumentName: shortName,
                        DisplayName: "Back"
                    });

                    angular.element("input[type='file']").val(null);

                    insItem.ScanDate = moment(new Date()).toDate();
                };

