                $scope.GetMasterSystemicHistory = function (val, type) {
                    var params = {
                        "ParentOrganizationId": ParentOrganizationId,
                        "OrganizationId": $scope.HospitalId,
                        "UserId": $scope.UserId,
                        "HistoryId": 0,
                        "PageSize": 10,
                        "PageNumber": 1,
                        "SearchText": val,
                        "Type": '',
                        "IsFrequent": "N"

                    };

                    if (params.SearchText == "") {
                        params.IsFrequent = "Y";
                    }

                    return eHnoteSettingsDataService.GetMasterSystemicHistory(params).then(function (resp) {
                        //console.log("Response Data:", resp.data);
                        if (resp.data.count !== 0) {
                            if (resp.data.SystemicHistory !== undefined) {
                                return resp.data.SystemicHistory.map(function (item) {
                                    return item;
                                });
                            }
                        }
                    });
                };

