                //---- Stop medication ----//

                $scope.StopCurrentSystemicMedication = function (item) {
                    var dosesupplytest = "";
                    if (item.DaysSupply !== '') {
                        dosesupplytest = " for " + item.DaysSupplyDescription;
                    }
                    item.Sig = item.Action + " " + item.Dose + " " + item.DoseUnit + " " + item.Route + " " + item.Frequency + " " + item.DoseOther + "" + dosesupplytest;
                    if (item.Sig.trim() == '') {
                        alertify.error("Please Select Sig ");
                        return false;
                    }
                    $uibModal.open({
                        "templateUrl": "templates/UsNewConsultation/uibpopup/StopMedication.html",
                        "backdrop": "static",
                        "size": "lg",
                        "keyboard": false,
                        "resolve": {
                            "MedicationDetails": function () { return item; },
                            "MedicationStopReasons": function () { return $scope.MedicationStopReasons || []; }
                        },
                        "controller": function ($scope, $uibModalInstance, MedicationDetails, MedicationStopReasons) {
                            $scope.MedicationStopReasons = MedicationStopReasons;

                            var StoppedDate = MedicationDetails.StopDate ? $filter('date')(MedicationDetails.StopDate, "MM-dd-yyyy") : null;
                            $scope.StopMedication = {
                                "StopDate": StoppedDate || $filter('date')(new window.Date(), "MM-dd-yyyy"),
                                "StopReason": MedicationDetails.StopReason || "",
                                "StopReasonId": MedicationDetails.StopReasonId || null,
                                "StopMedicationNotes": MedicationDetails.StopReason || ""
                            };

                            $scope.closeStopmedicationPopup = function () {
                                $uibModalInstance.dismiss("cancel");
                            };

                            $scope.changeStopMedication = function (StopReasonId) {
                                if (StopReasonId != null) {
                                    var ListArray = $filter("filter")($scope.MedicationStopReasons, { "StopReasonId": StopReasonId }, true);
                                    if (ListArray.length > 0) {
                                        $scope.StopMedication.StopMedicationNotes = ListArray[0].StopReason;
                                    }
                                } else {
                                    $scope.StopMedication.StopMedicationNotes = "";
                                }
                            };

                            $scope.StopmedicatioSave = function () {
                                if (!$scope.StopMedication.StopDate) {
                                    alertify.error("Please Select Stop Date");
                                    return false;
                                }
                                if ($scope.StopMedication.StopReasonId == '' || $scope.StopMedication.StopReasonId == null) {
                                    alertify.error("Please Select Stop Reason");
                                    return false;
                                }
                                var StopDate = new window.Date($scope.StopMedication.StopDate.split('-').join('/'));
                                var CurrentDate = new window.Date($filter('date')(new window.Date(), "MM/dd/yyyy"));

                                MedicationDetails.IsMedicationStopped = StopDate <= CurrentDate;
                                MedicationDetails.StopReason = $scope.StopMedication.StopMedicationNotes;
                                MedicationDetails.StopReasonId = $scope.StopMedication.StopReasonId;
                                MedicationDetails.StopDate = $scope.StopMedication.StopDate;
                                $uibModalInstance.close();
                            };
                        }
                    });
                };

