                $scope.SaveRosData = function () {
                    var RosOBj = {
                        "PatientId": PatientId,
                        "MasterPatientId": $scope.MasterPatientId,
                        "AppointmentId": AppointmentId,
                        "HospitalId": OrganizationId,
                        "AllergyItems": $scope.obj.AllergyItems || [],
                        "AllergyRemarks": $scope.obj.AllergyRemarks || "",
                        //"LifestyleHistory": $scope.obj.LifestyleHistoryArray || [],
                        "LifestyleHistory": ($scope.obj.LifestyleHistoryArray || []).filter(function (item) {
                            return item.MastertPatientDetailId || item.SmokingType || item.AlcoholType || item.DrugType || item.PsychisType;
                        }),
                        "LifestyleHistoryRemarks": $scope.obj.LifestyleHistoryRemarks || "",
                        "CurrentSystemicMedicationsHistory": $scope.obj.CurrentSystemicMedicationsHistory || [],
                        "CurrentSystemicRemarks": $scope.obj.CurrentSystemicRemarks || "",
                        "SystemicHistory": $scope.obj.SystemicHistoryArray || [],
                        "SystemicHistoryRemarks": $scope.obj.SystemicHistoryRemarks || "",
                    }

                    eHnotePatientAddressDataServices.AddupdateROSDataFrompatientPortal(RosOBj).then(function (response) {
                        if (response.data.Status === 'Success') {

                            alertify.success("Changes saved successfully");

                            if (response.data.SystemicHistory && response.data.SystemicHistory.length > 0) {
                                $scope.obj.SystemicHistoryArray = angular.copy(response.data.SystemicHistory) || [];
                                $scope.obj.SystemicHistoryArray.forEach(item => {
                                    if (item.HistoryId == 1) {
                                        $scope.obj.isNKSHSelected = true;
                                    }
                                    item.Duration = item.Duration || '';
                                    item.DurationType = item.DurationType || 'D';
                                    item.DurationDate = item.DurationDate || null;
                                    if (item.DurationDate != null) {
                                        item.ShowDateFormat = true;
                                        item.DurationDate = $filter('date')(item.DurationDate, "MM-dd-yyyy");
                                    } else {
                                        item.ShowDateFormat = false;
                                    }
                                })
                                //$scope.feildValidationObj.isMedicalHistory = isMedicalHistoryCompleted();

                            } else {
                                $scope.obj.SystemicHistoryArray = [];
                            }
                            if (response.data.AllergyItems.length > 0) {
                                $scope.obj.AllergyItems = angular.copy(response.data.AllergyItems) || [];
                                $scope.obj.AllergyItems.forEach(item => {
                                    if (item.AllergyId == 1) {
                                        $scope.obj.isNKASelected = true;
                                    } else if (item.AllergyId == 2) {
                                        $scope.obj.isNKDASelected = true;
                                    }
                                    item.Remarks = item.Remarks || '';
                                    item.ShowNote = item.Remarks != '';
                                    item.Duration = item.Duration || '';
                                    item.DurationType = item.DurationType || 'D';
                                    item.DurationDate = item.DurationDate || '';
                                    if (item.DurationDate != '') {
                                        item.ShowDateFormat = true;
                                        item.DurationDate = $filter('date')(item.DurationDate, "MM-dd-yyyy");
                                    } else {
                                        item.ShowDateFormat = false;
                                    }
                                    item.AllergyTypeId = item.AllergyTypeId ? parseInt(item.AllergyTypeId) : null;
                                    item.ReactionSearch = '';
                                    item.Reactions = item.Reactions || [];
                                    item.SelectedReactionIds = {};
                                    item.Reactions.forEach(reaction => {
                                        if (reaction.DeleteInd == 'N') {
                                            item.SelectedReactionIds[reaction.ReactionId] = true;
                                        }
                                    });
                                })
                                //$scope.feildValidationObj.isAllergies = isAllergiesCompleted();
                            } else {
                                $scope.obj.AllergyItems = [];
                            }
                            if (response.data.CurrentSystemicMedicationsHistory.length > 0) {
                                $scope.obj.CurrentSystemicMedicationsHistory = angular.copy(response.data.CurrentSystemicMedicationsHistory) || [];
                                $scope.obj.CurrentSystemicMedicationsHistory.forEach(item => {
                                    if (item.MedicineId == 2) {
                                        $scope.obj.isNKCSMSelected = true;
                                    }
                                    item.Remarks = item.Remarks || '';
                                    item.ShowNote = item.Remarks != '';
                                    item.MedicineObject = item.Sig || '';
                                    item.StartDate = item.StartDate ? $filter('date')(item.StartDate, "MM-dd-yyyy") : null;
                                })
                                //$scope.feildValidationObj.isMedicationList = isMedicationListCompleted();
                            } else {
                                $scope.obj.CurrentSystemicMedicationsHistory = [];
                            }
                            if (response.data.LifestyleHistory.length > 0) {
                                $scope.obj.LifestyleHistoryArray = angular.copy(response.data.LifestyleHistory) || [];
                                if ($scope.obj.LifestyleHistoryArray.length > 0) {
                                    angular.forEach($scope.obj.LifestyleHistoryArray, function (item) {
                                        if (item.HistoryId == 1) {
                                            $scope.obj.LifestyleHistory.SmokingType = item.SmokingType;
                                            item.SmokingStatusId = item.SmokingStatusId == 0 ? null : item.SmokingStatusId;
                                            if (item.SmokingFromDate != '' && item.SmokingFromDate != null) {
                                                item.SmokeShowDateFormat = true;
                                                item.SmokingFromDate = $filter('date')(item.SmokingFromDate, "MM-dd-yyyy");
                                            }
                                        }
                                        if (item.HistoryId == 2) {
                                            $scope.obj.LifestyleHistory.AlcoholType = item.AlcoholType;
                                            item.AlcoholStatusId = item.AlcoholStatusId == 0 ? null : item.AlcoholStatusId;
                                            if (item.AlcoholDurationDate != '' && item.AlcoholDurationDate != null) {
                                                item.AlcoShowDateFormat = true;
                                                item.AlcoholDurationDate = $filter('date')(item.AlcoholDurationDate, "MM-dd-yyyy");
                                            }
                                        }
                                        if (item.HistoryId == 3) {
                                            $scope.obj.LifestyleHistory.DrugType = item.DrugType;
                                            item.DrugQuantityId = item.DrugQuantityId == 0 ? null : item.DrugQuantityId;
                                            if (item.DrugDurationDate != '' && item.DrugDurationDate != null) {
                                                item.DrugShowDateFormat = true;
                                                item.DrugDurationDate = $filter('date')(item.DrugDurationDate, "MM-dd-yyyy");
                                            }
                                        }
                                        if (item.HistoryId == 4) {
                                            $scope.obj.LifestyleHistory.PsychisType = item.PsychisType;
                                            item.DeleteInd = 'N';
                                        }
                                    });
                                }
                            } else {
                                $scope.obj.LifestyleHistoryArray = [];
                            }
                            //$scope.feildValidationObj.isAllMedicalConditionsAdded = ($scope.feildValidationObj.isAllergies && $scope.feildValidationObj.isMedicationList && $scope.feildValidationObj.isMedicalHistory);
                            AfterPatientFormSave();
                        }
                    });
                }

