                $scope.OnClearPatientSignature = async function (pitem, index) {
                    // Topaz-only call; skip it on the drawing pad so it doesn't fire a request
                    // at the SigWeb bridge that isn't running.
                    if ($scope.signPlusObj.PatientSignBy == "Topaz") {
                        try {
                            await ClearTablet();
                        } catch (error) {
                            console.log("Error in ClearTablet:", error);
                        }
                    }

                    let canvas = document.getElementById("signPatientPadUD" + index);
                    if (canvas) {
                        var context = canvas.getContext('2d');
                        context.clearRect(0, 0, canvas.width, canvas.height);
                        pitem.PatientSignBy = 'Drawing';
                    }
                }

                function LoadSignatureOnCanvas(canvasId, signString) {
                    let canvas = document.getElementById(canvasId);
                    if (!canvas || !signString) {
                        return;
                    }
                    var context = canvas.getContext('2d');
                    context.clearRect(0, 0, canvas.width, canvas.height);
                    var image = new Image();
                    image.onload = function () {
                        context.drawImage(image, 0, 0);
                    };
                    image.src = signString;
                }

                $scope.EditPatientSignature = function (Citem, index) {
                    Citem.IsPatientDigitalSignTaken = false;
                    Citem.IsPatientSignatureDone = false;
                    $timeout(function () {
                        LoadSignatureOnCanvas("signPatientPadUD" + index, Citem.PatientSignString);
                    }, 100);
                }

                $scope.EditGaurdianSignature = function (Citem, index) {
                    Citem.IsGaurdianSignatureDone = false;
                    $timeout(function () {
                        LoadSignatureOnCanvas("signGaurdianPadUD" + index, Citem.GaurdianSignString);
                    }, 100);
                }

