                async function handleInsurance(identifierType) {
                    return new Promise((resolve) => {
                        let existing = $filter('filter')($scope.PatientInsuranceSummary, function (resp) {
                            return (resp.IdentifierId == identifierType && resp.StatusId == 1 && resp.DeleteInd == 'N' && resp.PatientInsuranceDetailId != 0);
                        });

                        let current = $filter('filter')($scope.PatientInsuranceSummary, function (resp) {
                            return (resp.IdentifierId == identifierType && resp.StatusId == 1 && resp.DeleteInd == 'N' && resp.PatientInsuranceDetailId == 0);
                        });

                        if (existing.length > 0 && current.length > 0) {
                            alertify.confirm(
                                `<h4 class='txt-body-centre'>This patient already has an active ${identifierType == 1 ? 'Primary' : identifierType == 2 ? 'Secondary' : 'Tertiary'
                                } insurance. Do you want to add the current insurance as active and deactivate the previous one?</h4>`,

                                function () {
                                    //  YES clicked
                                    angular.forEach($scope.PatientInsuranceSummary, function (item) {
                                        if (item.IdentifierId == identifierType) {
                                            item.InactiveActiveInsurance = (item.PatientInsuranceDetailId != 0);
                                            item.StatusId = item.PatientInsuranceDetailId == 0 ? 1 : 5;
                                        }
                                    });
                                    resolve(true);
                                },

                                function () {
                                    // ❌ NO clicked
                                    angular.forEach($scope.PatientInsuranceSummary, function (item) {
                                        if (item.IdentifierId == identifierType) {
                                            item.InactiveActiveInsurance = (item.PatientInsuranceDetailId == 0);
                                            item.StatusId = item.PatientInsuranceDetailId != 0 ? 1 : 5;
                                        }
                                    });
                                    resolve(false);
                                }
                            );
                        } else {
                            resolve(true);
                        }
                    });
                }



