    $scope.convertTo12HourFormat = function (time) {
        var hours = parseInt(time.substring(0, 2)); // Extract hours
        var minutes = time.substring(3, 5);        // Extract minutes
        var seconds = time.substring(6, 8);        // Extract seconds

        var ampm = hours >= 12 ? 'PM' : 'AM';      // Determine AM/PM
        hours = hours % 12;                         // Convert 24-hour to 12-hour format
        hours = hours ? hours : 12;                 // Handle the case for "00" as 12

        // Return the time in 12-hour format with AM/PM
        return hours + ':' + minutes + ' ' + ampm;
    };


